import pandas as pd

def get_holdings_detailed(file_path, accession_number):
    holdings = {}
    with open(file_path, 'r') as f:
        header = f.readline().strip().split('\t')
        cusip_idx = header.index('CUSIP')
        value_idx = header.index('VALUE')
        shares_idx = header.index('SSHPRNAMT')
        acc_idx = header.index('ACCESSION_NUMBER')

        for line in f:
            cols = line.strip().split('\t')
            if cols[acc_idx] == accession_number:
                cusip = cols[cusip_idx]
                try:
                    value = float(cols[value_idx])
                except ValueError:
                    value = 0.0
                try:
                    shares = float(cols[shares_idx])
                except ValueError:
                    shares = 0.0

                if cusip not in holdings:
                    holdings[cusip] = {'value': 0.0, 'shares': 0.0}
                holdings[cusip]['value'] += value
                holdings[cusip]['shares'] += shares
    return holdings

q2_acc = "0000950123-25-008343"
q3_acc = "0001193125-25-282901"

q2_holdings = get_holdings_detailed("/root/2025-q2/INFOTABLE.tsv", q2_acc)
q3_holdings = get_holdings_detailed("/root/2025-q3/INFOTABLE.tsv", q3_acc)

all_cusips = set(q2_holdings.keys()) | set(q3_holdings.keys())

increased_investments = []
for cusip in all_cusips:
    h2 = q2_holdings.get(cusip, {'value': 0.0, 'shares': 0.0})
    h3 = q3_holdings.get(cusip, {'value': 0.0, 'shares': 0.0})

    if h3['shares'] > h2['shares']:
        increased_investments.append({
            'cusip': cusip,
            'value_increase': h3['value'] - h2['value'],
            'shares_increase': h3['shares'] - h2['shares']
        })

increased_investments.sort(key=lambda x: x['value_increase'], reverse=True)

for i in range(min(5, len(increased_investments))):
    print(f"{increased_investments[i]['cusip']}: {increased_investments[i]['value_increase']}")

